function leerEml(contenido) {
  const t = String(contenido).replace(/\r\n/g, '\n');
  const corte = t.indexOf('\n\n');
  const cabecera = corte === -1 ? t : t.slice(0, corte);
  const cuerpo = corte === -1 ? '' : t.slice(corte + 2);
  const json = { textPlain: cuerpo, textHtml: '', metadata: {} };
  for (const linea of cabecera.split('\n')) {
    const m = linea.match(/^([A-Za-z-]+):\s*(.*)$/);
    if (!m) continue;
    const nombre = m[1].toLowerCase();
    if (['from', 'to', 'subject', 'date', 'cc'].includes(nombre)) json[nombre] = m[2];
    else json.metadata[nombre] = m[2];
  }
  return json;
}

// Cada .eml de ejemplo pasa a tener la misma forma que un correo del disparador IMAP.
return $input.all().map(i => ({ json: leerEml(i.json.data) }));

function huella(s) {
  // FNV-1a de 32 bits: identifica un correo sin Message-ID.
  let h = 0x811c9dc5;
  for (const c of String(s)) { h ^= c.codePointAt(0); h = Math.imul(h, 0x01000193) >>> 0; }
  return h.toString(16).padStart(8, '0');
}

// Una línea del banco: "Importe: 10,00 EUR" (Bizum) o "Importe .......... 12,00 EUR" (transferencia).
const lineaBanco = campo => new RegExp(`^[ \\t]*${campo}[ \\t]*(?::|\\.{2,})`, 'mi');

function prepararCorreo(c) {
  const remitente = String(c.from?.text ?? c.from ?? '');
  const asunto = String(c.subject ?? '');
  const texto = String(c.textPlain || String(c.textHtml ?? '').replace(/<[^>]+>/g, ' ')).trim();
  const messageId = c.metadata?.['message-id'] ?? '';
  const id_correo = messageId || 'huella-' + huella(`${remitente}\n${asunto}\n${texto}`);
  // Filtro previo sin IA: solo es un pago si trae las líneas "Importe" y "Ordenante" del banco.
  // Los avisos de los flujos llegan al mismo buzón pero nunca usan ese formato.
  const es_pago = lineaBanco('Importe').test(texto) && lineaBanco('Ordenante').test(texto);
  const tipo = /transferencia/i.test(`${asunto}\n${texto}`) ? 'transferencia' : 'bizum';
  return { id_correo, remitente, asunto, texto, tipo, es_pago };
}

// Cada correo se lee una sola vez: el disparador IMAP lo marca como leído.
// Si el banco avisa dos veces del mismo pago, lo detecta "Decidir" con los abonos de hoy.
return $input.all().map(i => ({ json: prepararCorreo(i.json) }));

function importeANumero(v) {
  if (typeof v === 'number') return Number.isFinite(v) ? Math.round(v * 100) / 100 : null;
  let t = String(v ?? '').replace(/eur|€|\s/gi, '');
  if (t.includes(',')) t = t.replace(/\./g, '').replace(',', '.');
  if (!/^\d+(\.\d+)?$/.test(t)) return null;
  return Math.round(Number(t) * 100) / 100;
}

function validarExtraccion(respuesta) {
  let datos = respuesta;
  if (typeof respuesta === 'string') {
    const m = respuesta.match(/\{[\s\S]*\}/);
    try { datos = m ? JSON.parse(m[0]) : null; } catch { datos = null; }
  }
  if (!datos || typeof datos !== 'object') {
    return { json_valido: false, ordenante: '', importe: null, concepto: '' };
  }
  const importe = importeANumero(datos.importe);
  return {
    json_valido: true,
    ordenante: String(datos.ordenante ?? '').trim(),
    importe: importe !== null && importe > 0 ? importe : null,
    concepto: String(datos.concepto ?? '').trim(),
  };
}

// El modelo solo ha extraído texto; aquí se comprueba y el importe pasa a número.
const correo = $('Preparar correo').item.json;
const extraccion = validarExtraccion($json.text);
return { json: { correo: { id_correo: correo.id_correo, remitente: correo.remitente, asunto: correo.asunto, tipo: correo.tipo },
  extraccion, id: '', texto: `${extraccion.ordenante} ${extraccion.concepto}`.trim() } };

function decidir(extraccion, busqueda, hoy) {
  const { ordenante, importe, concepto } = extraccion;
  const candidatos = busqueda?.candidatos ?? [];
  const pregunta = motivo => ({ accion: 'preguntar', motivo, apartado: null, candidatos });
  const rechazo = (motivo, apartado) => ({ accion: 'rechazar', motivo, apartado, candidatos });

  if (!extraccion.json_valido) return pregunta('No se han podido leer los datos del correo');
  if (!ordenante) return pregunta('El correo no dice quién paga');
  if (importe === null) return pregunta('El importe no se puede leer o no es un número positivo');
  if (!concepto) return pregunta('El pago no trae concepto');
  if (busqueda?.resultado === 'ninguno') return pregunta('Ningún apartado activo coincide con quien paga');
  if (busqueda?.resultado === 'varios') return pregunta('Hay varios apartados posibles');
  if (busqueda?.resultado !== 'unico' || candidatos.length !== 1) return pregunta('La búsqueda del apartado no ha dado un resultado claro');

  const a = candidatos[0];
  if (a.estado !== 'activo') return rechazo(`El apartado está ${a.estado}`, a);
  if (a.fecha_limite < hoy) return rechazo(`El apartado está fuera de plazo (venció el ${a.fecha_limite})`, a);
  if (importe > a.pendiente) return rechazo(`El importe (${importe} €) supera lo pendiente (${a.pendiente} €)`, a);
  return { accion: 'registrar', motivo: '', apartado: a, candidatos };
}

// Si ese apartado ya tiene hoy un abono del mismo importe (en la app o antes en este mismo lote),
// no se registra: puede ser el mismo pago avisado dos veces. Se pregunta a Marisa.
function decidirLote(previos, busquedas, abonosHoy, hoy) {
  if (previos.length !== busquedas.length) throw new Error('No cuadran los correos con las búsquedas de apartado');
  const yaHoy = abonosHoy.map(a => `${a.apartado_id}|${a.importe}`);
  return previos.map((p, i) => {
    const decision = decidir(p.extraccion, busquedas[i], hoy);
    if (decision.accion === 'registrar') {
      const clave = `${decision.apartado.id}|${p.extraccion.importe}`;
      const j = yaHoy.indexOf(clave);
      if (j !== -1) {
        yaHoy.splice(j, 1);
        return { correo: p.correo, extraccion: p.extraccion, decision: { accion: 'preguntar',
          motivo: `Posible pago duplicado: el apartado #${decision.apartado.id} ya tiene hoy un abono de ${p.extraccion.importe} €`,
          apartado: null, candidatos: [decision.apartado] } };
      }
      yaHoy.push(clave);
    }
    return { correo: p.correo, extraccion: p.extraccion, decision };
  });
}

// Las reglas deciden; el modelo de IA no interviene. Se ven todos los correos del lote a la vez
// para no registrar dos veces el mismo pago aunque lleguen los dos avisos juntos.
const previos = $('Validar datos extraídos').all().map(i => i.json);
const busquedas = $('Buscar apartado').all().map(i => i.json);
// "Abonos de hoy" saca un item vacío si no hay ninguno (alwaysOutputData).
const abonosHoy = $('Abonos de hoy').all().map(i => i.json).filter(a => a.id !== undefined);
const hoy = $now.setZone('Europe/Madrid').toISODate();
return decidirLote(previos, busquedas, abonosHoy, hoy).map(json => ({ json, pairedItem: { item: 0 } }));

// 201: abono registrado. 422: la app lo rechaza (detail puede ser texto o lista). Otro código es un error.
const previo = $('Decidir').item.json;
const { statusCode, body } = $json;
if (statusCode === 201) {
  return { json: { ...previo, registro: { ok: true, apartado: { ...previo.decision.apartado, pendiente: body.pendiente, estado: body.estado } } } };
}
if (statusCode === 422) {
  const d = body?.detail;
  return { json: { ...previo, registro: { ok: false, detalle: typeof d === 'string' ? d : JSON.stringify(d) } } };
}
throw new Error(`La tienda respondió ${statusCode} al registrar el abono: ${JSON.stringify(body)}`);

// para que el propio aviso nunca parezca un pago si vuelve a leerse del buzón.
function euros(n) { return n === null || n === undefined ? '¿?' : `${Number(n).toFixed(2).replace('.', ',')} €`; }

function redactarAviso({ correo, extraccion, decision, registro }) {
  const quien = extraccion.ordenante || '(sin nombre)';
  const cuanto = euros(extraccion.importe);
  const lineaApartado = a => `#${a.id} ${a.cliente} · ${a.producto} T${a.talla} · faltan ${euros(a.pendiente)} · vence el ${a.fecha_limite}`;
  const datos = [
    `- Quién paga: ${quien}`,
    `- Cantidad: ${cuanto}`,
    `- Concepto: ${extraccion.concepto || '(vacío)'}`,
    `- Tipo de pago: ${correo.tipo}`,
    `- Correo: «${correo.asunto}»`,
  ];
  let asunto, cabecera, cierre = [];
  if (registro?.ok) {
    asunto = `Transferencia registrada como bizum: ${quien}, ${cuanto}`;
    cabecera = [`Se ha registrado una transferencia en el apartado ${lineaApartado(registro.apartado)}.`,
      'La app no tiene la forma de pago "transferencia", así que consta como bizum.'];
  } else if (registro && !registro.ok) {
    asunto = `Pago NO registrado (la app lo rechazó): ${quien}, ${cuanto}`;
    cabecera = ['La app no ha aceptado el abono, así que no se ha registrado nada.', `Motivo de la app: ${registro.detalle}`];
  } else if (decision.accion === 'rechazar') {
    asunto = `Pago NO registrado: ${quien}, ${cuanto}`;
    cabecera = ['No se ha registrado nada.', `Motivo: ${decision.motivo}.`, `Apartado: ${lineaApartado(decision.apartado)}`];
    cierre = ['Decide tú qué hacer con este dinero (devolverlo o hablar con la clienta).'];
  } else {
    asunto = `Pago por revisar: ${quien}, ${cuanto}`;
    cabecera = ['No se ha registrado nada porque no está claro de qué apartado es.', `Motivo: ${decision.motivo}.`];
    cierre = decision.candidatos.length
      ? ['Apartados posibles:', ...decision.candidatos.map(a => '- ' + lineaApartado(a)), '', 'Si es de uno de ellos, regístralo a mano en la app.']
      : ['No hay ningún apartado activo que encaje. Si es de una clienta, regístralo a mano en la app.'];
  }
  const mensaje = ['Hola, Marisa:', '', ...cabecera, '', 'Datos del pago:', ...datos, '', ...cierre, '', 'Este aviso lo envía el flujo "03 - Abonos a distancia".']
    .join('\n').replace(/\n{3,}/g, '\n\n');
  return { destinatario: 'tienda', email: '', asunto, mensaje, contexto: `Pago de ${quien}` };
}

// Los cinco campos se llaman como las entradas de "SUB - Enviar notificación".
return { json: redactarAviso($json) };
